<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {useFormItem} from 'element-plus'
const {formItem}=useFormItem()
import {api} from '../api'
import MediaPreview from './MediaPreview.vue'
import {fileSize} from '../tag-color'
import {useAccount} from '../store'
const account=useAccount()
const props=withDefaults(defineProps<{modelValue:any;multiple?:boolean;images?:boolean;disabled?:boolean;accept?:string;inputType?:'selector'|'image'|'video'|'audio';types?:number[];selectable?:boolean;showInput?:boolean;valueKey?:string;showUpload?:boolean;showNetwork?:boolean;inputSize?:number;itemSize?:number;inputClass?:string;inputStyle?:Record<string,string>|string;style?:Record<string,string>|string;tabsType?:''|'card'|'border-card'}>(),{multiple:false,images:false,disabled:false,inputType:'selector',selectable:true,showInput:true,valueKey:'url',showUpload:true,showNetwork:true,inputSize:80,itemSize:130,tabsType:''}),emit=defineEmits(['update:modelValue','change','save','close','closed'])
const open=ref(false),rows=ref<any[]>([]),records=ref<Record<string,any>>({}),page=ref(1),pageSize=ref(10),total=ref(0),search=ref(''),category=ref<number|null>(null),uploadMethod=ref<number|null>(null),selected=ref<any[]>([]),tab=ref('library'),network=ref(''),preview=ref<any>()
const mode=computed(()=>props.images?'image':props.inputType),types=computed(()=>props.types|| (props.images?[0]:[0,1,2,3])),values=computed<any[]>(()=>props.multiple?props.modelValue||[]:props.modelValue==null||props.modelValue===''?[]:[props.modelValue])
const media=computed(()=>values.value.map(value=>props.valueKey==='url'?{url:value,name:decodeURIComponent(value.split('/').pop())}:records.value[String(value)]).filter(Boolean))
function remember(items:any[]){for(const row of items)records.value[String(row[props.valueKey])]=row}
watch(values,async items=>{if(props.valueKey!=='url'&&items.length){remember((await api('/api/system/file/',{params:{[props.valueKey+'__in']:items.join(','),limit:items.length}})).data)}},{immediate:true,deep:true})
async function load(){const result=await api('/api/system/file/',{params:{page:page.value,limit:pageSize.value,search:search.value,file_type__in:types.value.join(','),...(category.value!==null?{file_type:category.value}:{}),...(uploadMethod.value!==null?{upload_method:uploadMethod.value}:{})}});rows.value=result.data;total.value=result.total;remember(rows.value)}
async function show(){selected.value=[...values.value];open.value=true;await load()}
function choose(row:any){if(!props.selectable||props.disabled)return;const value=row[props.valueKey];selected.value=props.multiple?(selected.value.includes(value)?selected.value.filter(x=>x!==value):[...selected.value,value]):[value]}
function update(value:any){emit('update:modelValue',value);emit('change',value);nextTick(()=>formItem?.validate('change',()=>{}))}
function confirm(){const value=props.multiple?selected.value:selected.value[0]??'';update(value);emit('save',value,selected.value.map(item=>records.value[String(item)]));open.value=false}
function remove(index:number){update(props.multiple?values.value.filter((_,i)=>i!==index):'')}
async function deleteFile(row:any){await api(`/api/system/file/${row.id}/`,{method:'DELETE'});selected.value=selected.value.filter(value=>value!==row[props.valueKey]);if(values.value.includes(row[props.valueKey]))update(props.multiple?values.value.filter(value=>value!==row[props.valueKey]):'');delete records.value[String(row[props.valueKey])];await load()}
async function upload(files:FileList|File[]){for(const file of Array.from(files)){const data=new FormData();data.append('url',file);data.append('upload_method','1');const row=(await api('/api/system/file/',{method:'POST',data})).data;remember([row]);if(props.selectable)selected.value=props.multiple?[...selected.value,row[props.valueKey]]:[row[props.valueKey]]}await load()}
async function fetchNetwork(){const response=await fetch(network.value);if(!response.ok)throw new Error('下载失败：'+response.status);const blob=await response.blob();await upload([new File([blob],new URL(network.value).pathname.split('/').pop()!,{type:blob.type})]);tab.value='library'}
function drop(event:DragEvent){event.preventDefault();upload(event.dataTransfer!.files)}
defineExpose({open,show,clear:()=>update(props.multiple?[]:''),onDataChange:update,data:values})
</script>
<template><slot name="input" :values="values" :media="media" :show="show" :remove="remove" :disabled="disabled"><div v-if="showInput" class="file-picker" :class="inputClass" :style="[style,inputStyle]"><div v-for="(row,index) in media" :key="values[index]" class="file-preview"><el-image v-if="mode==='image'" :src="row.url" :preview-src-list="media.map(x=>x.url)" :style="{width:inputSize+'px',height:inputSize+'px'}" fit="cover"/><video v-else-if="mode==='video'" :src="row.url" controls :style="{width:inputSize+'px'}"/><audio v-else-if="mode==='audio'" :src="row.url" controls/><a v-else :href="row.url" target="_blank">{{row.name}}</a><el-button v-if="!disabled&&selectable" text @click="remove(index)">移除</el-button></div><el-button v-if="!disabled" @click="show">选择 / 上传{{mode==='image'?'图片':'文件'}}</el-button></div></slot>
<el-dialog v-model="open" @close="emit('close')" @closed="emit('closed');formItem?.validate('blur',()=>{})" :title="mode==='image'?'图片选择器':'文件选择器'" width="min(900px, calc(100vw - 24px))"><el-tabs v-model="tab" :type="tabsType"><el-tab-pane label="文件库" name="library"><div class="picker-search"><slot name="actionbar-left" :rows="rows" :selected="selected" :reload="load"/><el-input v-model="search" placeholder="搜索文件名" clearable @keyup.enter="page=1;load()" @clear="page=1;load()"/><el-select v-model="category" @change="page=1;load()"><el-option label="全部类型" :value="null"/><el-option v-for="index in types" :key="index" :label="['图片','视频','音频','其他'][index]" :value="index"/></el-select><el-select v-model="uploadMethod" @change="page=1;load()"><el-option label="全部来源" :value="null"/><el-option label="默认上传" :value="0"/><el-option label="选择器上传" :value="1"/></el-select><el-button @click="page=1;load()">搜索</el-button><slot name="actionbar-right" :rows="rows" :selected="selected" :reload="load"/></div><div class="picker-grid" :style="{'--item-size':itemSize+'px'}"><div v-for="row in rows" :key="row.id" role="button" tabindex="0" :class="{chosen:selected.includes(row[valueKey])}" @click="choose(row)" @keydown.enter.self="choose(row)" @keydown.space.self.prevent="choose(row)"><slot name="item" :file="row" :selected="selected.includes(row[valueKey])" :choose="choose" :preview="()=>preview=row"><img v-if="row.file_type===0" :src="row.url"/><span v-else class="picker-symbol">{{['图片','视频','音频','文件'][row.file_type]}}</span><strong :title="row.name">{{row.name}}</strong><small>{{fileSize(row.size)}}</small><el-button text @click.stop="preview=row">预览</el-button><el-button v-if="!disabled&&account.can('file:delete')" text type="danger" @click.stop="deleteFile(row)">删除</el-button></slot></div></div><slot v-if="!rows.length" name="empty" :reload="load"><el-empty description="暂无文件"/></slot><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,30,40,50]" :total="total" layout="total,sizes,prev,pager,next" @current-change="load" @size-change="page=1;load()"/></el-tab-pane>
<el-tab-pane v-if="showUpload&&!disabled" label="本地上传" name="upload"><div class="picker-drop" @dragover.prevent @drop="drop"><p>拖动文件到此处，或选择文件上传</p><input type="file" :multiple="multiple" :accept="accept||(mode==='image'?'image/*':undefined)" @change="upload(($event.target as HTMLInputElement).files!)"/></div></el-tab-pane><el-tab-pane v-if="showNetwork&&!disabled" label="网络文件" name="network"><el-input v-model="network" placeholder="请输入文件的完整 URL"/><el-button @click="fetchNetwork">下载并保存到文件库</el-button></el-tab-pane></el-tabs><template #footer><slot name="actionbar-bottom" :selected="selected" :confirm="confirm" :close="()=>open=false"><span v-if="selectable">已选择 {{selected.length}} 个文件</span><el-button @click="open=false">关闭</el-button><el-button v-if="selectable&&!disabled" type="primary" @click="confirm">确定选择</el-button></slot></template></el-dialog><MediaPreview v-model="preview"/></template>
<style scoped>.picker-search{display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap}.picker-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--item-size),1fr));gap:12px}.picker-grid>[role="button"]{border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color);color:inherit;padding:10px;display:flex;flex-direction:column;align-items:center;cursor:pointer}.picker-grid>[role="button"].chosen{border-color:var(--el-color-primary);background:var(--el-color-primary-light-9)}.picker-grid img,.picker-symbol{width:100%;height:100px;object-fit:contain}.picker-symbol{display:grid;place-items:center;color:var(--el-color-primary);font-size:24px}.picker-grid strong{max-width:100%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;margin:8px 0}.picker-drop{padding:50px 15px;text-align:center;border:2px dashed var(--el-border-color)}.el-pagination{margin-top:20px}.file-preview audio,.file-preview video{max-width:100%}@media(max-width:768px){.picker-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.picker-drop input{max-width:100%}.file-preview{max-width:100%;overflow-wrap:anywhere}}</style>
